<script setup lang="ts">
import {computed,onMounted,ref,reactive} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,errorText} from '../../api/zenflow/client';
interface Source {id:string;title:string;sourceVersion:string;approved:boolean;kind:string;locale:string;citationVisibility:string;topic:string;sourceLocator:string;sliceCount?:number;content?:string}
export interface ReferenceSelection {documentId:string;kind:string;locale:string;citationVisibility:string;mode?:'FIXED'|'RETRIEVAL'}
const props=withDefaults(defineProps<{selected?:ReferenceSelection[];standalone?:boolean}>(),{selected:()=>[],standalone:false});
const emit=defineEmits<{(event:'update:selected',value:ReferenceSelection[]):void}>();
const sources=ref<Source[]>([]),cursor=ref<string|null>(null),busy=ref(false),open=ref(false),editing=ref<Source>();
const form=reactive({title:'',content:'',kind:'MATERIAL',locale:'en',citationVisibility:'PUBLIC',topic:'',sourceLocator:'',approved:false});
interface PublishedRevision{active:boolean;revisionNo:number;state:string;retrievalPolicy:{references:ReferenceSelection[];maxFragments:number}}
const online=ref<PublishedRevision>(),publicationLoaded=ref(false),embeddingReady=ref(false);
const retrievalCount=computed(()=>online.value?.retrievalPolicy.references.filter(item=>item.mode!=='FIXED').length||0);
function onlineUse(source:Source){if(!publicationLoaded.value)return '线上使用状态未读取';if(!source.approved)return '未获使用授权';const selected=online.value?.retrievalPolicy.references.find(item=>item.documentId===source.id);if(!selected)return '未选入线上版本';return selected.mode==='FIXED'?'线上固定参考 · 已封存快照':'线上检索参考 · 已封存索引';}
async function loadPublication(){publicationLoaded.value=false;try{const [companion,embeddings]=await Promise.all([api.get('/companion'),api.get('/embedding-models')]);online.value=companion.data.status==='ENABLED'?companion.data.revisions.find((item:PublishedRevision)=>item.active):undefined;embeddingReady.value=embeddings.data.some((item:{active:boolean})=>item.active);publicationLoaded.value=true;}catch(e){ElMessage.error(errorText(e));}}
let original='';
const chosen=ref<Source>(),chunks=ref<{id:string;content:string;characters:number}[]>([]),chunkVersion=ref(''),fileInput=ref<HTMLInputElement>(),newChunk=ref('');
async function showChunks(source:Source){try{chosen.value=source;const data=(await api.get('/references/'+source.id+'/chunks')).data;chunks.value=data.items;chunkVersion.value=data.sourceVersion;}catch(e){ElMessage.error(errorText(e));}}
async function saveChunk(chunk:{id?:string;content:string},remove=false){if(!chosen.value)return;busy.value=true;try{const base='/references/'+chosen.value.id+'/chunks';const body={expectedSourceVersion:chunkVersion.value,...(remove?{}:{content:chunk.content})};if(remove)await ElMessageBox.confirm('删除此切片？已发布版本仍保留原快照。','删除切片');const result=(await(remove?api.delete(base+'/'+chunk.id,{data:body}):chunk.id?api.put(base+'/'+chunk.id,body):api.post(base,body))).data;await showChunks(result);await load();ElMessage.success('切片已保存');if(!chunk.id)newChunk.value='';}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function deleteSource(source:Source){try{await ElMessageBox.confirm('删除后所有版本将无法继续使用这份资料，相关引用立即失效。','删除资料',{type:'warning'});}catch{return;}busy.value=true;try{await api.delete('/references/'+source.id,{params:{expectedSourceVersion:source.sourceVersion}});remove(source.id);if(chosen.value?.id===source.id){chosen.value=undefined;chunks.value=[];}await load();}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>30*1024*1024){ElMessage.warning('文件最大 30 MB');return;}busy.value=true;try{const buffer=new Uint8Array(await file.arrayBuffer());let value='';for(let i=0;i<buffer.length;i+=8192)value+=String.fromCharCode(...buffer.subarray(i,i+8192));const data=(await api.post('/references/extract',{filename:file.name,base64:btoa(value)})).data;editing.value=undefined;Object.assign(form,{title:data.title,content:data.content,kind:'MATERIAL',locale:'zh-CN',citationVisibility:'PUBLIC',topic:'',sourceLocator:file.name,approved:false});original=JSON.stringify(form);open.value=true;}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;(event.target as HTMLInputElement).value='';}}
function setMode(id:string,mode:'FIXED'|'RETRIEVAL'){emit('update:selected',props.selected.map(ref=>ref.documentId===id?{...ref,mode}:ref));}

const stale=ref(new Set<string>());
function remove(id:string){stale.value.delete(id);emit('update:selected',props.selected.filter(x=>x.documentId!==id));}
async function load(more=false){busy.value=true;try{const page=(await api.get('/references',{params:more?{before:cursor.value}:undefined})).data;sources.value=more?[...sources.value,...page.items]:page.items;cursor.value=page.nextCursor;if(props.standalone&&!chosen.value&&sources.value.length)void showChunks(sources.value[0]);for(const selected of props.selected){const latest=sources.value.find(x=>x.id===selected.documentId);if(latest&&(!latest.approved||latest.kind!==selected.kind||latest.locale!==selected.locale||latest.citationVisibility!==selected.citationVisibility))stale.value.add(selected.documentId);}}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
function pick(source:Source,value:unknown){
 if(value&&!source.approved){ElMessage.warning('这份资料尚未批准，不能选入草稿');return;}
 stale.value.delete(source.id);
 const others=props.selected.filter(x=>x.documentId!==source.id);
 if(value&&others.length>=20){ElMessage.warning('最多选择 20 份参考资料');return;}
 emit('update:selected',value?[...others,{documentId:source.id,kind:source.kind,locale:source.locale,citationVisibility:source.citationVisibility}]:others);
}
async function edit(source?:Source){busy.value=true;try{editing.value=source;const data=source?(await api.get('/references/'+source.id)).data:undefined;Object.assign(form,data?{title:data.title,content:data.content,kind:data.kind,locale:data.locale,citationVisibility:data.citationVisibility,topic:data.topic||'',sourceLocator:data.sourceLocator||'',approved:data.approved}:{title:'',content:'',kind:'MATERIAL',locale:'en',citationVisibility:'PUBLIC',topic:'',sourceLocator:'',approved:false});if(data)editing.value=data;original=JSON.stringify(form);open.value=true;}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function close(done:()=>void){if(busy.value)return;if(JSON.stringify(form)!==original){try{await ElMessageBox.confirm('有未保存的资料修改，是否放弃？','放弃修改',{confirmButtonText:'放弃',cancelButtonText:'继续编辑'});}catch{return;}}done();}
async function save(){busy.value=true;try{if(form.approved)await ElMessageBox.confirm('请确认资料可以公开用于陪伴，不含用户私人信息，并已取得必要的使用授权。','批准公共陪伴使用',{confirmButtonText:'确认批准并保存',cancelButtonText:'返回检查'});const value=editing.value?{...form,expectedSourceVersion:editing.value.sourceVersion}:form;const data=(await (editing.value?api.put('/references/'+editing.value.id,value):api.post('/references',value))).data;if(props.selected.some(x=>x.documentId===data.id)){if(!data.approved)remove(data.id);else emit('update:selected',props.selected.map(x=>x.documentId===data.id?{...x,documentId:data.id,kind:data.kind,locale:data.locale,citationVisibility:data.citationVisibility}:x));}original=JSON.stringify(form);open.value=false;await load();ElMessage.success('资料已保存；已发布版本保持原有快照');}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function revoke(source:Source){try{await ElMessageBox.confirm('将立即撤销所有已发布版本对这份资料的使用，并停止依赖它的回答。','撤销资料授权',{confirmButtonText:'确认撤销',cancelButtonText:'取消',type:'warning'});}catch{return;}busy.value=true;try{await api.post('/references/'+source.id+'/revoke',{expectedSourceVersion:source.sourceVersion});emit('update:selected',props.selected.filter(x=>x.documentId!==source.id));await load();ElMessage.success('资料授权已撤销');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
onMounted(()=>{void load();if(props.standalone)void loadPublication();});
</script>
<template><section><div v-if="standalone" class="page-heading"><div><div class="eyebrow">KNOWLEDGE &amp; SOURCES</div><h1>参考资料</h1><p class="muted">资料列表、原文切片和编辑直接呈现。短资料可固定引用；长文按相关片段检索。</p></div></div><el-alert v-if="standalone&&publicationLoaded" :title="online?'线上版本 '+online.revisionNo+'：已选 '+online.retrievalPolicy.references.length+' 份资料，其中 '+retrievalCount+' 份参与检索。上传与批准不会自动发布。':'尚无已启用的陪伴版本，资料暂未用于聊天。'" :type="retrievalCount?'success':'warning'" :closable="false"/><el-alert v-if="standalone&&publicationLoaded&&!embeddingReady" title="尚未激活嵌入模型：长资料检索未就绪。请到模型配置的嵌入模型页签完成配置，再选入陪伴草稿、准备索引并发布。" type="warning" :closable="false"/><p class="muted">维护供陪伴使用的公共资料。只有明确批准的资料可以选入版本；私人记录通过用户自己的授权流程使用。</p><input ref="fileInput" type="file" accept=".txt,.md,.pdf,.docx" hidden @change="importFile"/><div class="actions"><el-button :disabled="busy" @click="fileInput?.click()">导入文件 · 最大 30 MB</el-button><el-button :disabled="busy" @click="edit()">新增文字资料</el-button><el-button :disabled="busy" @click="load();standalone&&loadPublication()">刷新资料</el-button></div><el-empty v-if="!sources.length&&!busy" description="尚无公共参考资料"/><div v-loading="busy"><article v-for="source in sources" :key="source.id" class="model-card" style="margin:12px 0"><div class="card-heading"><h2 v-if="standalone" style="cursor:pointer" @click="showChunks(source)">{{source.title}}</h2><el-checkbox v-else :model-value="selected.some(x=>x.documentId===source.id)" :disabled="busy||(!source.approved&&!selected.some(x=>x.documentId===source.id))" @change="pick(source,$event)">{{source.title}}</el-checkbox><el-tag :type="source.approved?'success':'info'">{{source.approved?'已批准':'待批准'}}</el-tag><el-tag v-if="standalone" :type="publicationLoaded&&source.approved&&online?.retrievalPolicy.references.some(item=>item.documentId===source.id)?'success':'warning'">{{onlineUse(source)}}</el-tag></div><p v-if="stale.has(source.id)" role="alert">资料或授权已变化，请取消后重新选择。</p><p class="muted">{{source.kind==='EXAMPLE'?'参考示例':'参考材料'}} · {{source.locale==='en'?'英文':'中文'}} · {{source.citationVisibility==='PUBLIC'?'可查看原文':source.citationVisibility==='TITLE_ONLY'?'仅展示标题':'内部参考'}}{{source.topic?' · '+source.topic:''}}</p><div class="actions"><el-button :disabled="busy" @click="edit(source)">编辑原文</el-button><el-button :disabled="busy" @click="showChunks(source)">切片 · {{source.sliceCount}}</el-button><el-button :disabled="busy" type="danger" text @click="deleteSource(source)">删除</el-button><el-select v-if="selected.some(x=>x.documentId===source.id)" :model-value="selected.find(x=>x.documentId===source.id)?.mode||'RETRIEVAL'" @change="setMode(source.id,$event)"><el-option label="固定短参考 · 无需嵌入模型" value="FIXED"/><el-option label="长资料检索" value="RETRIEVAL"/></el-select><el-button v-if="source.approved" :disabled="busy" type="danger" plain @click="revoke(source)">撤销授权</el-button></div></article></div><el-button v-if="cursor" :disabled="busy" @click="load(true)">更多资料</el-button><p v-if="!standalone" class="muted">已选择 {{selected.length}} / 20 份资料。选择需与陪伴草稿一同保存。</p><div class="actions"><el-tag v-for="item in selected" :key="item.documentId" closable @close="remove(item.documentId)">{{sources.find(s=>s.id===item.documentId)?.title||'所选资料 '+item.documentId}}</el-tag></div>
<section v-if="chosen" class="model-card"><h2>{{chosen.title}} · 原文切片</h2><p class="muted">编辑切片只影响后续准备的版本。共 {{chunks.length}} 个切片。</p><article v-for="(chunk,index) in chunks" :key="chunk.id" style="margin:16px 0"><h3>切片 {{index+1}} · {{chunk.characters}} 字符</h3><el-input v-model="chunk.content" type="textarea" :rows="5" maxlength="16000"/><div class="actions"><el-button :disabled="busy" @click="saveChunk(chunk)">保存此切片</el-button><el-button :disabled="busy||chunks.length<2" type="danger" text @click="saveChunk(chunk,true)">删除切片</el-button></div></article><el-input v-model="newChunk" type="textarea" :rows="3" maxlength="16000" placeholder="新增切片原文"/><el-button :disabled="busy||!newChunk.trim()" @click="saveChunk({content:newChunk})">新增切片</el-button></section>
<el-dialog v-model="open" append-to-body title="公共参考资料" width="min(800px,94vw)" :close-on-click-modal="false" :before-close="close"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title" maxlength="200"/></el-form-item><div class="actions"><el-select v-model="form.kind"><el-option label="参考材料" value="MATERIAL"/><el-option label="参考示例" value="EXAMPLE"/></el-select><el-select v-model="form.locale"><el-option label="英文" value="en"/><el-option label="中文" value="zh-CN"/></el-select><el-select v-model="form.citationVisibility"><el-option label="可查看原文" value="PUBLIC"/><el-option label="仅展示标题" value="TITLE_ONLY"/><el-option label="内部参考" value="INTERNAL"/></el-select></div><el-form-item label="主题"><el-input v-model="form.topic" maxlength="200"/></el-form-item><el-form-item label="出处 / 章节"><el-input v-model="form.sourceLocator" maxlength="512"/></el-form-item><el-form-item label="资料原文"><el-input v-model="form.content" type="textarea" :rows="12" maxlength="400000" show-word-limit/></el-form-item><el-checkbox v-model="form.approved">确认资料可公开用于陪伴并批准使用</el-checkbox><p class="muted">内部参考仅控制引用卡片展示；模型仍会读取资料。隐藏原文不能代替公开使用授权。</p></el-form><template #footer><el-button :disabled="busy" @click="close(()=>open=false)">取消</el-button><el-button :loading="busy" type="primary" @click="save">保存资料</el-button></template></el-dialog>
</section></template>
